/* DXN Achievement Crowd Audio — V1
   Plays the supplied 5-second crowd applause/cheer when the 90+ trophy celebration appears.
   No external audio URL is required.
*/
(function () {
  if (window.__DXN_ACHIEVEMENT_CROWD_AUDIO_V1__) return;
  window.__DXN_ACHIEVEMENT_CROWD_AUDIO_V1__ = true;

  var AUDIO_DATA = "data:audio/mpeg;base64,";
  var audio = null;

  function play() {
    try {
      if (!audio) {
        audio = new Audio(AUDIO_DATA);
        audio.preload = "auto";
        audio.volume = 0.95;
      }
      audio.currentTime = 0;
      var p = audio.play();
      if (p && typeof p.catch === "function") p.catch(function () {});
    } catch (e) {}
  }

  window.playDXNAchievementCrowd = play;
})();